package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceDocumentController;import com.rpb.reservation.workforce.documents.*;import static com.rpb.reservation.workforce.documents.DocumentDtos.*;
import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.workforce.domain.WorkforceException;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceDocumentApiTest {
 CurrentActorProvider actors=mock(CurrentActorProvider.class);EmployeeDocumentService service=mock(EmployeeDocumentService.class);UUID store=UUID.randomUUID(),employee=UUID.randomUUID(),doc=UUID.randomUUID(),file=UUID.randomUUID();String base="/api/v1/stores/"+store+"/workforce";MockMvc mvc=MockMvcBuilders.standaloneSetup(new WorkforceDocumentController(actors,service)).build();
 String files(){return base+"/employees/"+employee+"/documents/"+doc+"/attachments/"+file;}
 void login(){when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of(store))));}
 @Test void privateDocumentReadsRequireAuthenticationAndCannotCache()throws Exception{for(var path:List.of(base+"/document-types",base+"/employees/"+employee+"/documents",files()))mvc.perform(get(path)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));verifyNoInteractions(service);}
 @Test void writesAreProtectedAndConflictsUseStableCodes()throws Exception{for(var path:List.of(base+"/document-types/"+doc,base+"/employees/"+employee+"/documents/"+doc,files()+"/deletion")){mvc.perform(put(path).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put(path).header("X-RPB-Workforce","1").header("Sec-Fetch-Site","cross-site").contentType("application/json").content("{}")).andExpect(status().isForbidden());}verifyNoInteractions(service);login();when(service.save(any(),any(),any(),any(),any())).thenThrow(WorkforceException.conflict());mvc.perform(put(base+"/employees/"+employee+"/documents/"+doc).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isConflict()).andExpect(header().string("Cache-Control","private, no-store"));}
 @Test void attachmentDownloadUsesPrivateSafeAttachmentResponse()throws Exception{login();when(service.download(any(),eq(store),eq(employee),eq(doc),eq(file))).thenReturn(new FileData(file,"证件.pdf","application/pdf","%PDF-1.7".getBytes(),"a".repeat(64),false));mvc.perform(get(files())).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Cache-Control","private, no-store")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.startsWith("attachment;"))).andExpect(content().contentType("application/pdf"));}
}
